INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-16-norway-mandate-pulled-forward', 'en', 'Norway pulls its B2B e-invoicing mandate forward a full year, to January 2027', 'Norway''s Ministry of Finance has instructed the tax authority to prepare for mandatory B2B e-invoice issuance from 1 January 2027 — a full year earlier than the 2028 date originally proposed — citing that roughly half of the country''s 140 million annual B2B invoices already move through Peppol.', '<h3>🇳🇴 Norway pulls its B2B e-invoicing mandate forward a full year, to January 2027</h3>
<p>Following a public consultation launched in summer 2025, Norway''s Ministry of Finance issued a formal instruction to the Directorate of Taxes on this date, moving the planned start of mandatory B2B e-invoice issuance a full year earlier than originally proposed — from 1 January 2028 to 1 January 2027. The rationale given is genuinely concrete rather than aspirational: roughly half of Norway''s estimated 140 million annual B2B and B2G invoices already move electronically through the Peppol network, around 70 Peppol BIS-compliant solutions are already active among private businesses, and approximately 90% of invoices to Norwegian public entities are already structured e-invoices. The government''s own conclusion was straightforward — the market is digitally ready and doesn''t need an additional year of runway.</p>
<p>Worth understanding the model clearly: Norway operates on a post-audit, interoperability-first basis via the EHF (Elektronisk Handelsformat) format — Norway''s national profile of Peppol BIS Billing 3.0 — genuinely different from the clearance-based continuous transaction control models used in Italy, Turkey, or Saudi Arabia. There''s no government validation step before an invoice becomes legally valid; compliance is instead monitored through periodic reporting and audits, including mandatory monthly transaction-count reporting from Peppol Access Point providers already in place since 2024. Sole proprietorships with turnover below NOK 50,000 remain exempt if not VAT-registered.</p>
<p><strong>What this means for your team:</strong> if your business already operates on the Peppol network, this accelerated deadline is largely a formalisation of existing practice, not a major new build. If you''re still relying on PDF or paper invoicing for Norwegian B2B trade, the compliance runway just shortened by a full year — worth treating this as more urgent than the original 2028 planning horizon suggested.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-19-norway-law-enacted', '2026-06-19', '2026-06', 'Norway''s Storting has formally enacted the Act on Amendments to the Bookkeeping Act (Law-2026-06-19-39), confirming the transition from proposal to binding statutory regime — mandatory issuance from January 2027, mandatory reception and digital bookkeeping from January 2030.', '<h3>🇳🇴 Bookkeeping Act amendments formally enacted, confirming binding B2B e-invoicing law</h3>
<p>What began as Prop. 44 L (2025-2026) has now been formally gazetted as binding statutory law: the Act on Amendments to the Bookkeeping Act and Certain Other Laws in the Financial Market Area, Law-2026-06-19-39. This moves Norway''s e-invoicing reform from proposal to enacted legislation, introducing formal statutory definitions of "mandatory accounting reporting," "electronic accounting system," and — notably — "electronic invoice" itself, defined as a sales document issued, sent, and received in a structured electronic format suitable for automated processing.</p>
<p>The phased structure is now legally confirmed rather than merely proposed: from 1 January 2027, all businesses subject to Norwegian bookkeeping obligations must issue e-invoices to other businesses registered in ELMA, Norway''s national Peppol participant directory — critically, this obligation is specifically conditional on the buyer actually being ELMA-registered, not a universal requirement regardless of counterparty. From 1 January 2030, mandatory reception and compulsory use of certified digital bookkeeping systems extends to entities not already caught by the 2027 mandate. One practical consequence worth being direct about: PDF invoices sent to ELMA-registered counterparties will simply no longer be valid from 2027 onward.</p>
<p><strong>What this means for your team:</strong> before issuing any invoice from 2027 onward, check whether your counterparty is actually registered in ELMA — this determines whether the structured e-invoicing obligation applies to that specific transaction or not, rather than applying blanket across every invoice you send. Given this is now enacted law rather than a proposal still subject to change, treat the 2027 date as genuinely fixed for your planning purposes.</p>', 'https://www.skatteetaten.no', 1);
