INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-19-norway-law-enacted', 'en', 'Bookkeeping Act amendments formally enacted, confirming binding B2B e-invoicing law', 'Norway''s Storting has formally enacted the Act on Amendments to the Bookkeeping Act (Law-2026-06-19-39), confirming the transition from proposal to binding statutory regime — mandatory issuance from January 2027, mandatory reception and digital bookkeeping from January 2030.', '<h3>🇳🇴 Bookkeeping Act amendments formally enacted, confirming binding B2B e-invoicing law</h3>
<p>What began as Prop. 44 L (2025-2026) has now been formally gazetted as binding statutory law: the Act on Amendments to the Bookkeeping Act and Certain Other Laws in the Financial Market Area, Law-2026-06-19-39. This moves Norway''s e-invoicing reform from proposal to enacted legislation, introducing formal statutory definitions of "mandatory accounting reporting," "electronic accounting system," and — notably — "electronic invoice" itself, defined as a sales document issued, sent, and received in a structured electronic format suitable for automated processing.</p>
<p>The phased structure is now legally confirmed rather than merely proposed: from 1 January 2027, all businesses subject to Norwegian bookkeeping obligations must issue e-invoices to other businesses registered in ELMA, Norway''s national Peppol participant directory — critically, this obligation is specifically conditional on the buyer actually being ELMA-registered, not a universal requirement regardless of counterparty. From 1 January 2030, mandatory reception and compulsory use of certified digital bookkeeping systems extends to entities not already caught by the 2027 mandate. One practical consequence worth being direct about: PDF invoices sent to ELMA-registered counterparties will simply no longer be valid from 2027 onward.</p>
<p><strong>What this means for your team:</strong> before issuing any invoice from 2027 onward, check whether your counterparty is actually registered in ELMA — this determines whether the structured e-invoicing obligation applies to that specific transaction or not, rather than applying blanket across every invoice you send. Given this is now enacted law rather than a proposal still subject to change, treat the 2027 date as genuinely fixed for your planning purposes.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-01-norway-explores-b2c-expansion', '2026-04-01', '2026-04', 'Alongside the accelerated B2B mandate, Norway''s Ministry of Finance has tasked the Directorate of Taxes with formally investigating whether e-invoicing requirements should extend to B2C transactions, whether digital sales receipts should become mandatory, and whether accounting software providers should face new regulatory requirements — with findings due by December 2026.', '<h3>🇳🇴 Norway explores extending e-invoicing beyond B2B: e-receipts, B2C, and software regulation</h3>
<p>Alongside formally accelerating the B2B mandate, Norway''s Ministry of Finance gave the Directorate of Taxes a genuinely broader assignment worth watching closely: a formal investigation into whether e-invoicing and digital reporting requirements should extend well beyond business-to-business trade. Three specific questions are on the table. First, whether mandatory e-invoicing requirements should extend to B2C transactions — invoices to consumers, not just other businesses. Second, whether digital sales receipts (e-receipts) should be mandated outright, standardising digital records for point-of-sale transactions in a way Norway hasn''t yet required. Third, whether accounting system providers themselves should face new regulatory requirements specifically tied to the incoming digital bookkeeping mandate.</p>
<p>This exploration is due to conclude by December 2026 — a genuinely near-term deadline given how significant any of these three expansions would be if adopted. None of the three has been decided or even formally proposed yet; this is explicitly investigative work, not a confirmed future mandate. But the direction is worth noting: Norway is already moving toward what industry commentary has termed "platformisation of compliance" — treating e-invoicing as one layer of a broader digital compliance infrastructure rather than a standalone requirement.</p>
<p><strong>What this means for your team:</strong> none of these three potential expansions are confirmed yet, so there''s no immediate action required based on this investigation alone. But if your business has significant B2C sales volume, or you''re an accounting software provider serving the Norwegian market, this December 2026 report is worth watching directly rather than assuming the current B2B-only scope is where things will settle.</p>', 'https://www.skatteetaten.no', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-04-01-norway-explores-b2c-expansion', id FROM countries WHERE name_en = 'Norway';
